    GuardQuiet(r);
    int trail = g.Trail;
    r.Takedown("guard", "kill"); r.Done(Enf);
    var a = ActOn(r, GuardId); var b = g.BodyById("guard")!;
    r.Is(b.Dead && b.Open, "dead, lying at his post");
